create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, role text not null default 'customer' check(role in ('owner','staff','customer')), created_at timestamptz not null default now());
create table if not exists public.menu_items(id uuid primary key default gen_random_uuid(),name text not null,category text not null,description text not null default '',price numeric(10,2) not null check(price>=0),available boolean not null default true,image_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),order_no bigint generated by default as identity,table_no int check(table_no between 1 and 3),order_type text not null default 'Dine-in' check(order_type in ('Dine-in','Takeaway','Parcel')),customer_name text,customer_phone text,status text not null default 'new' check(status in ('new','accepted','preparing','ready','served','cancelled')),total numeric(10,2) not null default 0,payment_method text check(payment_method in ('Cash','UPI','Card')),paid_at timestamptz,notes text,tracking_token uuid not null unique default gen_random_uuid(),created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,item_id uuid references public.menu_items(id) on delete set null,item_name text not null,unit_price numeric(10,2) not null,quantity int not null check(quantity>0),note text);
create index if not exists orders_status_created_idx on public.orders(status,created_at);
create index if not exists order_items_order_idx on public.order_items(order_id);
alter table public.profiles enable row level security; alter table public.menu_items enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('owner','staff')); $$;
create policy "menu is public" on public.menu_items for select using (true);
create policy "staff manage menu" on public.menu_items for all using (public.is_staff()) with check (public.is_staff());
create policy "staff read profiles" on public.profiles for select using (id=auth.uid() or public.is_staff());
create policy "customer create orders" on public.orders for insert with check (status='new');
create policy "staff manage orders" on public.orders for all using (public.is_staff()) with check (public.is_staff());
create policy "staff read order items" on public.order_items for select using (public.is_staff());
create policy "customer add order items" on public.order_items for insert with check (exists(select 1 from public.orders o where o.id=order_id and o.status='new'));
create or replace function public.place_order(p_table_no int,p_order_type text,p_customer_name text,p_customer_phone text,p_items jsonb)
returns table(id uuid,order_no bigint,tracking_token uuid,total numeric) language plpgsql security definer set search_path=public as $$
declare v_order_id uuid; v_total numeric(10,2):=0; v_token uuid; v_no bigint; v_line jsonb; v_item public.menu_items%rowtype; v_qty int;
begin
 if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Cart is empty'; end if;
 if p_order_type not in ('Dine-in','Takeaway','Parcel') then raise exception 'Invalid order type'; end if;
 if p_order_type='Dine-in' and (p_table_no is null or p_table_no not between 1 and 3) then raise exception 'Select a valid table'; end if;
 for v_line in select * from jsonb_array_elements(p_items) loop
   select * into v_item from public.menu_items where id=(v_line->>'item_id')::uuid and available=true;
   if not found then raise exception 'An item is unavailable. Refresh the menu.'; end if;
   v_qty:=(v_line->>'quantity')::int; if v_qty<1 or v_qty>30 then raise exception 'Invalid quantity'; end if;
   v_total:=v_total+(v_item.price*v_qty);
 end loop;
 insert into public.orders(table_no,order_type,customer_name,customer_phone,total,status) values(case when p_order_type='Dine-in' then p_table_no else null end,p_order_type,nullif(trim(p_customer_name),''),nullif(trim(p_customer_phone),''),v_total,'new') returning orders.id,orders.order_no,orders.tracking_token into v_order_id,v_no,v_token;
 for v_line in select * from jsonb_array_elements(p_items) loop
   select * into v_item from public.menu_items where id=(v_line->>'item_id')::uuid;
   v_qty:=(v_line->>'quantity')::int;
   insert into public.order_items(order_id,item_id,item_name,unit_price,quantity,note) values(v_order_id,v_item.id,v_item.name,v_item.price,v_qty,nullif(trim(v_line->>'note'),''));
 end loop;
 return query select v_order_id,v_no,v_token,v_total;
end; $$;
create or replace function public.track_order(p_token uuid) returns table(order_no bigint,status text,created_at timestamptz) language sql security definer set search_path=public as $$ select o.order_no,o.status,o.created_at from public.orders o where o.tracking_token=p_token; $$;
revoke all on function public.place_order(int,text,text,text,jsonb) from public; grant execute on function public.place_order(int,text,text,text,jsonb) to anon,authenticated;
revoke all on function public.track_order(uuid) from public; grant execute on function public.track_order(uuid) to anon,authenticated;
grant usage on schema public to anon,authenticated; grant select on public.menu_items to anon,authenticated; grant insert,select,update on public.orders to anon,authenticated; grant insert,select on public.order_items to anon,authenticated; grant select on public.profiles to authenticated;
-- Enable realtime updates for the kitchen queue in Supabase.
do $$ begin alter publication supabase_realtime add table public.orders; exception when duplicate_object then null; when undefined_object then null; end $$;
